    state.texted = state.texted || {};
    const last = ((state.texted[bizId] || {})[ev.from]) || null;
    const windowMs = Number(s.dedupe_window_hours || 24) * 3600 * 1000;
    if (optouts[bizId] && optouts[bizId][ev.from]) {
